import seedCatalog from "../public/products.json";

const JSON_HEADERS={"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff"};
const enc=new TextEncoder();
const ADMIN_ROLES=new Set(["OWNER","ADMIN"]);
const ORDER_STATUSES=new Set(["NEW","ACCEPTED","PENDING_PAYMENT","PAID","PACKING","PACKED","SHIPPED","COMPLETED","CANCELLED"]);
const NEXT_STATUS={NEW:["ACCEPTED","CANCELLED"],ACCEPTED:["PACKING","CANCELLED"],PENDING_PAYMENT:["PAID","CANCELLED"],PAID:["PACKING","CANCELLED"],PACKING:["PACKED","PAID","ACCEPTED","CANCELLED"],PACKED:["SHIPPED","PACKING","CANCELLED"],SHIPPED:["COMPLETED"],COMPLETED:[],CANCELLED:[]};

function json(data,init={}){return new Response(JSON.stringify(data),{...init,headers:{...JSON_HEADERS,...(init.headers||{})}})}
function b64(bytes){let s="";for(const byte of bytes)s+=String.fromCharCode(byte);return btoa(s).replaceAll("+","-").replaceAll("/","_").replaceAll("=","")}
function fromB64(value){const normalized=value.replaceAll("-","+").replaceAll("_","/");const raw=atob(normalized+"=".repeat((4-normalized.length%4)%4));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
function b64json(value){return b64(enc.encode(JSON.stringify(value)))}
function clean(value,max=200){return String(value??"").trim().slice(0,max)}
function number(value,min=0,max=1e9){const n=Number(value);return Number.isFinite(n)&&n>=min&&n<=max?n:null}
function sameOrigin(request){const origin=request.headers.get("origin");return !origin||origin===new URL(request.url).origin}
function requireOrigin(request){return sameOrigin(request)?null:json({error:"invalid_origin"},{status:403})}
function randomToken(){const bytes=new Uint8Array(32);crypto.getRandomValues(bytes);return b64(bytes)}
function orderId(){const d=new Date(),date=`${String(d.getUTCFullYear()).slice(-2)}${String(d.getUTCMonth()+1).padStart(2,"0")}${String(d.getUTCDate()).padStart(2,"0")}`,suffix=crypto.randomUUID().replaceAll("-","").slice(0,8).toUpperCase();return`OD${date}-${suffix}`}
function sessionCookie(token){return`jigz_sid=${encodeURIComponent(token)}; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=31536000`}
function readCookie(request){const match=(request.headers.get("cookie")||"").match(/(?:^|;\s*)jigz_sid=([^;]+)/);return match?decodeURIComponent(match[1]):""}
async function digest(value){return new Uint8Array(await crypto.subtle.digest("SHA-256",enc.encode(value)))}
async function tokenHash(token){return b64(await digest(token))}
async function parseBody(request){const type=request.headers.get("content-type")||"";if(!type.includes("application/json"))throw new Error("invalid_content_type");const length=Number(request.headers.get("content-length")||0);if(length>1600000)throw new Error("payload_too_large");const text=await request.text();if(text.length>1600000)throw new Error("payload_too_large");try{return JSON.parse(text||"{}") }catch{throw new Error("invalid_json")}}
function normalizedImages(value,maxCount=5){if(!Array.isArray(value))return[];if(value.length>maxCount)throw new Error("too_many_images");const images=[];let total=0;for(const raw of value){const image=String(raw??"").trim();if(!image)continue;const remote=image.startsWith("https://")&&image.length<=2000,data=/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(image)&&image.length<=240000;if(!remote&&!data)throw new Error("invalid_image");total+=image.length;if(total>1250000)throw new Error("payload_too_large");if(!images.includes(image))images.push(image)}if(images.length>maxCount)throw new Error("too_many_images");return images}
async function ensureColumn(db,table,column,definition){let columns=await db.prepare(`PRAGMA table_info(${table})`).all();if(columns.results.some(item=>item.name===column))return;try{await db.prepare(`ALTER TABLE ${table} ADD COLUMN ${column} ${definition}`).run()}catch(error){columns=await db.prepare(`PRAGMA table_info(${table})`).all();if(!columns.results.some(item=>item.name===column))throw error}}
let databaseInitPromise=null;
