async function currentUser(request,db){const token=readCookie(request);if(!token)return null;return(await db.prepare("SELECT u.id,u.display_name,u.role,u.status,u.is_primary_owner FROM user_sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires_at>CURRENT_TIMESTAMP AND u.status='ACTIVE'").bind(await tokenHash(token)).first())||null}
async function newUser(db,role){const id=crypto.randomUUID(),token=randomToken(),hash=await tokenHash(token),expires=new Date(Date.now()+31536000000).toISOString(),displayName=`JIGZ-${id.slice(0,8).toUpperCase()}`,primary=role==="OWNER"?1:0;await db.batch([db.prepare("INSERT INTO users(id,display_name,role,is_primary_owner) VALUES(?,?,?,?)").bind(id,displayName,role,primary),db.prepare("INSERT INTO user_sessions(token_hash,user_id,expires_at) VALUES(?,?,?)").bind(hash,id,expires),db.prepare("INSERT INTO user_profiles(user_id) VALUES(?)").bind(id)]);return{user:{id,display_name:displayName,role,status:"ACTIVE",is_primary_owner:primary},cookie:sessionCookie(token)}}
