async function getProfile(db,userId){return(await db.prepare("SELECT full_name,phone,address,avatar_image,points,updated_at FROM user_profiles WHERE user_id=?").bind(userId).first())||{full_name:"",phone:"",address:"",avatar_image:"",points:0}}
