async function createWithdrawalRequest(db,user,body){const amount=number(body.amount,100,1e7),bankName=clean(body.bankName,100),accountName=clean(body.accountName,160),accountNumber=clean(body.accountNumber,60);if(amount===null||!bankName||!accountName||!/^[0-9 -]{6,30}$/.test(accountNumber))return{error:"invalid_withdrawal",status:400};await db.prepare("INSERT OR IGNORE INTO wallet_accounts(user_id,balance) VALUES(?,0)").bind(user.id).run();const account=await db.prepare("SELECT balance FROM wallet_accounts WHERE user_id=?").bind(user.id).first();if(Number(account?.balance||0)<amount)return{error:"insufficient_credit",status:409};const id=financeId("WD"),transactionId=financeId("TX");try{await db.batch([db.prepare("INSERT INTO wallet_requests(id,user_id,type,amount,status,bank_name,bank_account_name,bank_account_number,verification_status) VALUES(?,?,'WITHDRAWAL',?,'PENDING',?,?,?,'IDENTITY_REVIEW')").bind(id,user.id,amount,bankName,accountName,accountNumber.replace(/\s|-/g,"")),db.prepare("UPDATE wallet_accounts SET balance=balance-?,updated_at=CURRENT_TIMESTAMP WHERE user_id=?").bind(amount,user.id),db.prepare("INSERT INTO wallet_transactions(id,user_id,type,direction,amount,status,reference_type,reference_id,description) VALUES(?,?,'WITHDRAWAL_HOLD','DEBIT',?,'POSTED','WITHDRAWAL',?,'กันยอดสำหรับคำขอถอนเครดิต')").bind(transactionId,user.id,amount,id)])}catch(error){if(String(error).includes("insufficient_credit"))return{error:"insufficient_credit",status:409};throw error}await audit(db,user,"CREATE_WALLET_WITHDRAWAL","WALLET_REQUEST",id,{amount,bankName});return{ok:true,id,status:"PENDING",wallet:await walletSnapshot(db,user.id)}}
async function reviewWalletRequest(db,actor,id,next,note=""){const request=await db.prepare("SELECT * FROM wallet_requests WHERE id=?").bind(id).first();if(!request)return{error:"wallet_request_not_found",status:404};if(request.status!=="PENDING")return{error:"wallet_request_processed",status:409};if(!["APPROVED","REJECTED"].includes(next))return{error:"invalid_wallet_status",status:400};const statements=[];if(request.type==="DEPOSIT"&&next==="APPROVED"){statements.push(db.prepare("INSERT OR IGNORE INTO wallet_accounts(user_id,balance) VALUES(?,0)").bind(request.user_id));statements.push(db.prepare("INSERT INTO wallet_transactions(id,user_id,type,direction,amount,status,reference_type,reference_id,description,actor_id) VALUES(?,?,'DEPOSIT','CREDIT',?,'POSTED','DEPOSIT',?,'แอดมินอนุมัติเติมเครดิต',?)").bind(financeId("TX"),request.user_id,request.amount,id,actor.id));statements.push(db.prepare("UPDATE wallet_accounts SET balance=balance+?,updated_at=CURRENT_TIMESTAMP WHERE user_id=?").bind(request.amount,request.user_id))}if(request.type==="WITHDRAWAL"&&next==="REJECTED"){statements.push(db.prepare("INSERT INTO wallet_transactions(id,user_id,type,direction,amount,status,reference_type,reference_id,description,actor_id) VALUES(?,?,'WITHDRAWAL_REFUND','CREDIT',?,'POSTED','WITHDRAWAL_REFUND',?,'คืนเครดิตจากคำขอถอนที่ไม่ผ่าน',?)").bind(financeId("TX"),request.user_id,request.amount,id,actor.id));statements.push(db.prepare("UPDATE wallet_accounts SET balance=balance+?,updated_at=CURRENT_TIMESTAMP WHERE user_id=?").bind(request.amount,request.user_id))}statements.push(db.prepare("UPDATE wallet_requests SET status=?,review_note=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='PENDING'").bind(next,clean(note,500),actor.id,id));await db.batch(statements);await audit(db,actor,`${next}_WALLET_${request.type}`,"WALLET_REQUEST",id,{amount:Number(request.amount),userId:request.user_id});return{ok:true,status:next}}
async function releaseWeeklyCommissions(db,actor={id:"SYSTEM_CRON"}){const rows=await db.prepare("SELECT c.id,c.order_id,c.commission_amount,a.user_id,a.code FROM sales_commissions c JOIN agents a ON a.id=c.agent_id JOIN sales_orders o ON o.id=c.order_id WHERE c.status IN ('PENDING','APPROVED') AND o.status='COMPLETED' AND o.deleted_at IS NULL AND a.status='ACTIVE' AND a.user_id IS NOT NULL AND a.user_id<>'' AND c.commission_amount>0 ORDER BY c.id LIMIT 500").all();let paid=0,total=0,offsetTotal=0;for(const row of rows.results){const amount=Number(row.commission_amount),referenceId=String(row.id),reversals=await db.prepare("SELECT id,amount FROM wallet_transactions WHERE user_id=? AND type='COMMISSION_REVERSAL' AND status='PENDING' ORDER BY created_at,id LIMIT 100").bind(row.user_id).all(),statements=[db.prepare("INSERT OR IGNORE INTO wallet_accounts(user_id,balance) VALUES(?,0)").bind(row.user_id)];let offset=0;for(const reversal of reversals.results){if(offset>=amount)break;const available=Number(reversal.amount),applied=Math.min(available,amount-offset);if(applied<=0)continue;offset+=applied;if(applied>=available-.009)statements.push(db.prepare("UPDATE wallet_transactions SET status='APPLIED' WHERE id=? AND status='PENDING'").bind(reversal.id));else statements.push(db.prepare("UPDATE wallet_transactions SET amount=amount-? WHERE id=? AND status='PENDING'").bind(applied,reversal.id));statements.push(db.prepare("INSERT OR IGNORE INTO wallet_transactions(id,user_id,type,direction,amount,status,reference_type,reference_id,description,actor_id) VALUES(?,?,'COMMISSION_OFFSET','DEBIT',?,'POSTED','COMMISSION_OFFSET',?,?,?)").bind(financeId("TX"),row.user_id,applied,`${referenceId}:${reversal.id}`,`หักค่าคอมจากบิลคืน/ลบกับ ${row.order_id}`,actor.id))}const net=Math.max(0,amount-offset);if(net>0){statements.push(db.prepare("UPDATE wallet_accounts SET balance=balance+?,updated_at=CURRENT_TIMESTAMP WHERE user_id=?").bind(net,row.user_id));statements.push(db.prepare("INSERT OR IGNORE INTO wallet_transactions(id,user_id,type,direction,amount,status,reference_type,reference_id,description,actor_id) VALUES(?,?,'COMMISSION','CREDIT',?,'POSTED','COMMISSION',?,?,?)").bind(financeId("TX"),row.user_id,net,referenceId,`ค่าคอมสุทธิออเดอร์ ${row.order_id}`,actor.id))}statements.push(db.prepare("UPDATE sales_commissions SET status='PAID',approved_at=COALESCE(approved_at,CURRENT_TIMESTAMP),paid_at=COALESCE(paid_at,CURRENT_TIMESTAMP) WHERE id=?").bind(row.id));await db.batch(statements);paid++;total+=net;offsetTotal+=offset}if(paid)await audit(db,actor,"RELEASE_WEEKLY_COMMISSIONS","COMMISSION",null,{paid,total,offsetTotal});return{paid,total,offsetTotal}}
async function transitionOrder(db,actor,id,next,extra={}){const order=await db.prepare("SELECT * FROM sales_orders WHERE id=? AND deleted_at IS NULL").bind(id).first();if(!order)throw new Error("order_not_found");next=clean(next,30).toUpperCase();if(!ORDER_STATUSES.has(next)||!NEXT_STATUS[order.status]?.includes(next))throw new Error("invalid_transition");const isPackingRollback=order.status==="PACKED"&&next==="PACKING"||order.status==="PACKING"&&["PAID","ACCEPTED"].includes(next),expectedPrePacking=order.payment_method==="COD"?"ACCEPTED":"PAID",rollbackReason=clean(extra.reason,300);if(order.status==="PACKING"&&["PAID","ACCEPTED"].includes(next)&&next!==expectedPrePacking)throw new Error("invalid_transition");if(isPackingRollback&&!rollbackReason)throw new Error("rollback_reason_required");if(next==="COMPLETED"&&order.payment_method==="COD"&&!order.cod_received_at)throw new Error("cod_payment_required");const statements=[];if(next==="CANCELLED"){const items=await db.prepare("SELECT product_id,quantity,actual_cost FROM sales_order_items WHERE order_id=?").bind(id).all();for(const item of items.results){statements.push(db.prepare("UPDATE products SET stock=COALESCE(stock,0)+?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(item.quantity,item.product_id));statements.push(db.prepare("INSERT INTO inventory_movements(product_id,movement_type,quantity,note) VALUES(?,'CANCEL_RETURN',?,?)").bind(item.product_id,item.quantity,`Cancelled ${id}`));statements.push(db.prepare("INSERT INTO inventory_lots(product_id,received_qty,remaining_qty,unit_cost,note) VALUES(?,?,?,?,?)").bind(item.product_id,item.quantity,item.quantity,Number(item.actual_cost)/Math.max(1,Number(item.quantity)),`Restore ${id}`))}}
 const trackingCompany=clean(extra.trackingCompany,80),trackingNumber=clean(extra.trackingNumber,120);if(next==="SHIPPED"&&(!trackingCompany||!trackingNumber))throw new Error("tracking_required");
 statements.push(db.prepare("UPDATE sales_orders SET status=?,tracking_company=CASE WHEN ?<>'' THEN ? ELSE tracking_company END,tracking_number=CASE WHEN ?<>'' THEN ? ELSE tracking_number END,paid_at=CASE WHEN ?='PAID' THEN COALESCE(paid_at,CURRENT_TIMESTAMP) ELSE paid_at END,shipped_at=CASE WHEN ?='SHIPPED' THEN CURRENT_TIMESTAMP ELSE shipped_at END,completed_at=CASE WHEN ?='COMPLETED' THEN CURRENT_TIMESTAMP ELSE completed_at END,cancelled_at=CASE WHEN ?='CANCELLED' THEN CURRENT_TIMESTAMP ELSE cancelled_at END,reservation_expires_at=CASE WHEN ? IN ('ACCEPTED','PAID','PACKING','PACKED','SHIPPED','COMPLETED','CANCELLED') THEN NULL ELSE reservation_expires_at END,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(next,trackingCompany,trackingCompany,trackingNumber,trackingNumber,next,next,next,next,next,id));await db.batch(statements);
 if(next==="COMPLETED"&&order.user_id){const rateSettings=await settings(db,true),points=Math.floor(Number(order.total)/Math.max(1,Number(rateSettings.points_rate||100)));if(points>0){try{await db.batch([db.prepare("INSERT INTO points_ledger(user_id,order_id,type,points,reason,actor_id) VALUES(?,?,'EARN',?,'ยืนยันรับสินค้า',?)").bind(order.user_id,id,points,actor.id),db.prepare("UPDATE user_profiles SET points=points+?,updated_at=CURRENT_TIMESTAMP WHERE user_id=?").bind(points,order.user_id)])}catch(error){if(!String(error).includes("UNIQUE"))throw error}}}
 await recalculateCommission(db,id);await audit(db,actor,isPackingRollback?"ROLLBACK_PACKING_STATUS":"TRANSITION_ORDER","ORDER",id,{from:order.status,to:next,trackingCompany,trackingNumber,reason:rollbackReason});return orderDetail(db,id)
}

async function orderDeletionStatements(db,actor,order){const statements=[],items=await db.prepare("SELECT product_id,product_name,quantity,actual_cost FROM sales_order_items WHERE order_id=?").bind(order.id).all();let returnedQuantity=0;if(order.status==="COMPLETED"){for(const item of items.results){const quantity=Number(item.quantity||0),unitCost=Number(item.actual_cost||0)/Math.max(.001,quantity);if(quantity<=0)continue;returnedQuantity+=quantity;statements.push(db.prepare("UPDATE products SET stock=COALESCE(stock,0)+?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(quantity,item.product_id));statements.push(db.prepare("INSERT INTO inventory_movements(product_id,movement_type,quantity,note) VALUES(?,'DELETE_RETURN',?,?)").bind(item.product_id,quantity,`Deleted order ${order.id} by ${actor.display_name||actor.id}`));statements.push(db.prepare("INSERT INTO inventory_lots(product_id,received_qty,remaining_qty,unit_cost,note) VALUES(?,?,?,?,?)").bind(item.product_id,quantity,quantity,unitCost,`คืนสต็อกจากออเดอร์ที่ลบ ${order.id}`))}const earned=await db.prepare("SELECT COALESCE(SUM(points),0) points FROM points_ledger WHERE order_id=? AND type='EARN'").bind(order.id).first(),points=Math.max(0,Number(earned?.points||0));if(points>0&&order.user_id){statements.push(db.prepare("INSERT OR IGNORE INTO points_ledger(user_id,order_id,type,points,reason,actor_id) VALUES(?,?,'DELETE_REVERSAL',?,'คืนแต้มจากออเดอร์ที่ลบ',?)").bind(order.user_id,order.id,-points,actor.id));statements.push(db.prepare("UPDATE user_profiles SET points=MAX(0,points-?),updated_at=CURRENT_TIMESTAMP WHERE user_id=?").bind(points,order.user_id))}const commission=await db.prepare("SELECT c.id,c.status,c.commission_amount,a.user_id FROM sales_commissions c JOIN agents a ON a.id=c.agent_id WHERE c.order_id=?").bind(order.id).first();if(commission?.status==="PAID"&&commission.user_id&&Number(commission.commission_amount)>0){statements.push(db.prepare("INSERT OR IGNORE INTO wallet_transactions(id,user_id,type,direction,amount,status,reference_type,reference_id,description,actor_id) VALUES(?,?,'COMMISSION_REVERSAL','DEBIT',?,'PENDING','COMMISSION_REVERSAL',?,?,?)").bind(financeId("TX"),commission.user_id,Number(commission.commission_amount),String(commission.id),`รอหักค่าคอมคืนจากออเดอร์ ${order.id}`,actor.id));statements.push(db.prepare("UPDATE sales_commissions SET status='REVERSED' WHERE id=?").bind(commission.id))}else statements.push(db.prepare("UPDATE sales_commissions SET status='REVERSED',commission_amount=0,approved_at=NULL WHERE order_id=? AND status<>'PAID'").bind(order.id))}return{statements,returnedQuantity,itemCount:items.results.length}}

function closingPeriod(periodType,periodKey){const type=clean(periodType,10).toUpperCase(),key=clean(periodKey,10);if(type==="DAY"&&!/^\d{4}-\d{2}-\d{2}$/.test(key))return null;if(type==="MONTH"&&!/^\d{4}-\d{2}$/.test(key))return null;const parts=key.split("-").map(Number),year=parts[0],month=parts[1],day=type==="DAY"?parts[2]:1;if(year<2020||year>2100||month<1||month>12||day<1||day>31)return null;const localDate=new Date(Date.UTC(year,month-1,day));if(localDate.getUTCFullYear()!==year||localDate.getUTCMonth()!==month-1||localDate.getUTCDate()!==day)return null;const startMs=localDate.getTime()-7*3600000,endMs=type==="DAY"?startMs+86400000:Date.UTC(year,month,1)-7*3600000;return{type,key,start:new Date(startMs).toISOString(),end:new Date(endMs).toISOString()}}
function closingNumber(value){return Number(Number(value||0).toFixed(2))}
async function calculateClosing(db,periodType,periodKey){const period=closingPeriod(periodType,periodKey);if(!period)return null;const paidAt="CASE WHEN o.payment_method='COD' THEN o.cod_received_at ELSE o.paid_at END",[sales,cost,wallet,commission,pending]=await db.batch([db.prepare(`SELECT COUNT(*) order_count,COALESCE(SUM(o.subtotal),0) gross_sales,COALESCE(SUM(o.discount),0) discount_total,COALESCE(SUM(o.shipping_fee),0) shipping_total,COALESCE(SUM(o.total),0) revenue_total,COALESCE(SUM(CASE WHEN o.payment_method='TRANSFER' THEN o.total ELSE 0 END),0) transfer_total,COALESCE(SUM(CASE WHEN o.payment_method='CASH' THEN o.total ELSE 0 END),0) cash_total,COALESCE(SUM(CASE WHEN o.payment_method='COD' THEN o.total ELSE 0 END),0) cod_total FROM sales_orders o WHERE o.deleted_at IS NULL AND o.status<>'CANCELLED' AND ${paidAt}>=? AND ${paidAt}<?`).bind(period.start,period.end),db.prepare(`SELECT COALESCE(SUM(i.actual_cost),0) actual_cost FROM sales_order_items i JOIN sales_orders o ON o.id=i.order_id WHERE o.deleted_at IS NULL AND o.status<>'CANCELLED' AND ${paidAt}>=? AND ${paidAt}<?`).bind(period.start,period.end),db.prepare("SELECT COALESCE(SUM(CASE WHEN type='DEPOSIT' THEN amount ELSE 0 END),0) wallet_deposit_total,COALESCE(SUM(CASE WHEN type='WITHDRAWAL' THEN amount ELSE 0 END),0) wallet_withdrawal_total FROM wallet_requests WHERE status='APPROVED' AND reviewed_at>=? AND reviewed_at<?").bind(period.start,period.end),db.prepare("SELECT COALESCE(SUM(c.commission_amount),0) commission_total FROM sales_commissions c JOIN sales_orders o ON o.id=c.order_id WHERE o.deleted_at IS NULL AND c.status='PAID' AND c.paid_at>=? AND c.paid_at<?").bind(period.start,period.end),db.prepare("SELECT COUNT(*) pending_order_count,COALESCE(SUM(total),0) pending_order_total FROM sales_orders WHERE deleted_at IS NULL AND status IN ('NEW','ACCEPTED','PENDING_PAYMENT') AND created_at>=? AND created_at<?").bind(period.start,period.end)]),row=sales.results[0]||{},actualCost=closingNumber(cost.results[0]?.actual_cost),revenue=closingNumber(row.revenue_total),grossProfit=closingNumber(revenue-actualCost),commissionTotal=closingNumber(commission.results[0]?.commission_total);return{periodType:period.type,periodKey:period.key,periodStart:period.start,periodEnd:period.end,orderCount:Number(row.order_count||0),grossSales:closingNumber(row.gross_sales),discountTotal:closingNumber(row.discount_total),shippingTotal:closingNumber(row.shipping_total),revenueTotal:revenue,transferTotal:closingNumber(row.transfer_total),cashTotal:closingNumber(row.cash_total),codTotal:closingNumber(row.cod_total),actualCost,grossProfit,commissionTotal,netProfit:closingNumber(grossProfit-commissionTotal),walletDepositTotal:closingNumber(wallet.results[0]?.wallet_deposit_total),walletWithdrawalTotal:closingNumber(wallet.results[0]?.wallet_withdrawal_total),pendingOrderCount:Number(pending.results[0]?.pending_order_count||0),pendingOrderTotal:closingNumber(pending.results[0]?.pending_order_total)}}
function mapClosing(row){const snapshot=JSON.parse(row.snapshot_json||"{}");return{...row,...snapshot,orderCount:Number(row.order_count),grossSales:Number(row.gross_sales),discountTotal:Number(row.discount_total),shippingTotal:Number(row.shipping_total),revenueTotal:Number(row.revenue_total),transferTotal:Number(row.transfer_total),cashTotal:Number(row.cash_total),codTotal:Number(row.cod_total),actualCost:Number(row.actual_cost),grossProfit:Number(row.gross_profit),commissionTotal:Number(row.commission_total),walletDepositTotal:Number(row.wallet_deposit_total),walletWithdrawalTotal:Number(row.wallet_withdrawal_total),pendingOrderCount:Number(row.pending_order_count),pendingOrderTotal:Number(row.pending_order_total),actualCash:row.actual_cash===null?null:Number(row.actual_cash),cashDifference:row.cash_difference===null?null:Number(row.cash_difference),snapshot_json:undefined}}
async function createClosing(db,actor,body){const preview=await calculateClosing(db,body.periodType,body.periodKey);if(!preview)return{error:"invalid_closing_period",status:400};const actualCash=body.actualCash===""||body.actualCash===null||body.actualCash===undefined?null:number(body.actualCash,0,1e10);if(body.actualCash!==""&&body.actualCash!==null&&body.actualCash!==undefined&&actualCash===null)return{error:"invalid_actual_cash",status:400};const id=financeId(preview.periodType==="DAY"?"CD":"CM"),difference=actualCash===null?null:closingNumber(actualCash-preview.cashTotal),note=clean(body.note,500);try{await db.prepare("INSERT INTO financial_closings(id,period_type,period_key,period_start,period_end,order_count,gross_sales,discount_total,shipping_total,revenue_total,transfer_total,cash_total,cod_total,actual_cost,gross_profit,commission_total,wallet_deposit_total,wallet_withdrawal_total,pending_order_count,pending_order_total,actual_cash,cash_difference,note,snapshot_json,closed_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(id,preview.periodType,preview.periodKey,preview.periodStart,preview.periodEnd,preview.orderCount,preview.grossSales,preview.discountTotal,preview.shippingTotal,preview.revenueTotal,preview.transferTotal,preview.cashTotal,preview.codTotal,preview.actualCost,preview.grossProfit,preview.commissionTotal,preview.walletDepositTotal,preview.walletWithdrawalTotal,preview.pendingOrderCount,preview.pendingOrderTotal,actualCash,difference,note,JSON.stringify({netProfit:preview.netProfit}),actor.id).run()}catch(error){if(String(error).includes("UNIQUE"))return{error:"closing_exists",status:409};throw error}await audit(db,actor,"CREATE_FINANCIAL_CLOSING","FINANCIAL_CLOSING",id,{periodType:preview.periodType,periodKey:preview.periodKey,revenueTotal:preview.revenueTotal,cashDifference:difference});return{ok:true,closing:mapClosing(await db.prepare("SELECT f.*,u.display_name closed_by_name FROM financial_closings f JOIN users u ON u.id=f.closed_by WHERE f.id=?").bind(id).first())}}

async function addAlert(db,severity,type,title,message,entityType=null,entityId=null){const duplicate=await db.prepare("SELECT id FROM system_alerts WHERE status='OPEN' AND alert_type=? AND COALESCE(entity_id,'')=COALESCE(?,'') LIMIT 1").bind(type,entityId).first();if(duplicate)return duplicate.id;const result=await db.prepare("INSERT INTO system_alerts(severity,alert_type,title,message,entity_type,entity_id) VALUES(?,?,?,?,?,?)").bind(severity,type,title,message,entityType,entityId).run();return result.meta.last_row_id}
async function cleanupExpiredReservations(db){const expired=await db.prepare("SELECT id FROM sales_orders WHERE deleted_at IS NULL AND status IN ('NEW','PENDING_PAYMENT') AND reservation_expires_at IS NOT NULL AND reservation_expires_at<=CURRENT_TIMESTAMP ORDER BY reservation_expires_at LIMIT 50").all();let released=0;for(const row of expired.results){try{await transitionOrder(db,{id:"SYSTEM_RESERVATION",display_name:"ระบบจองสินค้า"},row.id,"CANCELLED",{});await addAlert(db,"INFO","RESERVATION_EXPIRED","คืนสต๊อกจากออเดอร์หมดเวลา",`ออเดอร์ ${row.id} ไม่ยืนยันภายในเวลาที่กำหนด ระบบคืนสินค้าแล้ว`,"ORDER",row.id);released++}catch(error){console.error(JSON.stringify({event:"reservation_release_failed",orderId:row.id,message:String(error)}))}}return released}
async function systemHealth(db,env){const [orders,stock,alerts,push,failedSlips,approvals,accessRequests]=await db.batch([db.prepare("SELECT COUNT(*) total FROM sales_orders WHERE deleted_at IS NULL AND status IN ('NEW','PENDING_PAYMENT') AND reservation_expires_at<=CURRENT_TIMESTAMP"),db.prepare("SELECT COUNT(*) total FROM products WHERE status='ACTIVE' AND COALESCE(stock,0)<=0"),db.prepare("SELECT COUNT(*) total FROM system_alerts WHERE status='OPEN'"),db.prepare("SELECT COUNT(*) total FROM push_subscriptions WHERE status='ACTIVE'"),db.prepare("SELECT COUNT(*) total FROM slip_verifications WHERE status NOT IN ('VERIFIED','NOT_CONFIGURED') AND created_at>=datetime('now','-24 hours')"),db.prepare("SELECT COUNT(*) total FROM approval_requests WHERE status='PENDING' AND expires_at>CURRENT_TIMESTAMP"),db.prepare("SELECT COUNT(*) total FROM admin_access_requests WHERE status='PENDING'")]);return{ok:true,version:"5.12.1",database:"connected",checks:{adminAccess:"DEVICE_APPROVAL",pendingAdminDevices:Number(accessRequests.results[0]?.total||0),expiredReservations:Number(orders.results[0]?.total||0),outOfStock:Number(stock.results[0]?.total||0),openAlerts:Number(alerts.results[0]?.total||0),pushSubscribers:Number(push.results[0]?.total||0),failedSlips24h:Number(failedSlips.results[0]?.total||0),pendingApprovals:Number(approvals.results[0]?.total||0),easySlip:env.EASYSLIP_API_KEY?"CONFIGURED":"NOT_CONFIGURED",timeTravel:"CLOUDFLARE_D1"},checkedAt:new Date().toISOString()}}
