async function ensureVapidKeys(db){const existing=await db.prepare("SELECT setting_value FROM system_settings WHERE setting_key='vapid_keys'").first();if(existing?.setting_value)return JSON.parse(existing.setting_value);const pair=await crypto.subtle.generateKey({name:"ECDSA",namedCurve:"P-256"},true,["sign","verify"]),privateJwk=await crypto.subtle.exportKey("jwk",pair.privateKey),publicJwk=await crypto.subtle.exportKey("jwk",pair.publicKey),x=fromB64(publicJwk.x),y=fromB64(publicJwk.y),point=new Uint8Array(65);point[0]=4;point.set(x,1);point.set(y,33);const generated={privateJwk,publicKey:b64(point)};await db.prepare("INSERT OR IGNORE INTO system_settings(setting_key,setting_value) VALUES('vapid_keys',?)").bind(JSON.stringify(generated)).run();const saved=await db.prepare("SELECT setting_value FROM system_settings WHERE setting_key='vapid_keys'").first();return JSON.parse(saved.setting_value)}
